import datetime,json,os,pathlib,shutil,subprocess
def emit(stage,**values):
 print(json.dumps({"stage":stage,**values}),flush=True)
def run(command,seconds=8):
 try:
  p=subprocess.run(command,text=True,capture_output=True,timeout=seconds)
  return {"exit_code":p.returncode,"stdout":p.stdout[-1500:],"stderr":p.stderr[-500:]}
 except subprocess.TimeoutExpired:
  return {"state":"TIMED_OUT","seconds":seconds}
 except Exception as e:
  return {"state":"UNAVAILABLE","reason":type(e).__name__}
emit("node",observed_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),user=os.getenv("USER"),worker_service=run(["systemctl","is-active","amx-black.service"],3))
binary=shutil.which("codex")
emit("linux_codex",path=binary,auth_file_present=(pathlib.Path.home()/".codex/auth.json").exists(),version=run([binary,"--version"],8) if binary else {"state":"NOT_ON_PATH"})
p=run(["ps","-eo","pid,comm,etime,stat,%cpu,%mem"],3)
emit("installation_processes",processes=[line for line in p.get("stdout","").splitlines() if any(word in line.lower() for word in ("codex","node","npm","wsl","python"))])
powershell=shutil.which("powershell.exe")
if powershell:
 cmd="$c=Get-Command codex -ErrorAction SilentlyContinue; if($c){$c.Source; & codex --version}else{Write-Output 'CODEX_NOT_ON_WINDOWS_PATH'}"
 emit("windows_codex",result=run([powershell,"-NoProfile","-NonInteractive","-Command",cmd],10))
else:
 emit("windows_codex",state="WINDOWS_INTEROP_NOT_ON_PATH")
emit("done")
